before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
struct Trace {
    Trace() { std::cout << "enter\n"; }
    ~Trace() { std::cout << "leave\n"; }
};
int main() {
    {
        Trace marker;
        std::cout << "work\n";
    }
    std::cout << "after\n";
}

```

